// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(address initiator, address from, uint256 tokenId, bytes calldata data) public {
        // The reference contract must always acknowledge safe NFT receipt with the
        // canonical ERC721TokenReceiver selector, for every caller, sender, id and payload.
        bytes4 returned = c.onERC721Received(initiator, from, tokenId, data);
        assertTrue(
            returned == ERC721TokenReceiver.onERC721Received.selector,
            "onERC721Received must return the canonical selector"
        );
    }
}

contract ERC721TokenReceiver {
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external pure returns (bytes4) {
        return this.onERC721Received.selector;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // keep baseToken nonzero so reference and buggy versions provably differ
        vm.assume(baseToken != address(0));
        vm.assume(nft != address(0));
        vm.assume(feeRate <= 5_000); // admissible domain for initialize

        c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // Universal rule: after initialize, the stored base token always equals the supplied one.
        assertTrue(c.baseToken() == baseToken);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseTokenArg,
        address nftArg,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        vm.assume(baseTokenArg != nftArg);

        bool ok;
        try c.initialize(
            baseTokenArg,
            nftArg,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(
            !ok || c.baseToken() == baseTokenArg,
            "initialize must store the supplied _baseToken in baseToken"
        );
    }
}

